import itertools, numpy as np
n=3; q=1.7
def R():
    M=np.zeros((n*n,n*n))
    for i in range(n):
        for j in range(n):
            if i==j: M[i*n+i,i*n+i]=q
            else: M[i*n+j,i*n+j]=1
            if i>j: M[i*n+j, j*n+i]+=q-1/q   # e_ij (x) e_ji : maps e_j(x)e_i -> e_i (x) e_j
    return M
Rm=R(); P=np.zeros((n*n,n*n))
for i in range(n):
    for j in range(n): P[i*n+j,j*n+i]=1
R21=P@Rm@P
cands={'R,Rinv':(Rm,np.linalg.inv(Rm)),'R21inv,R21':(np.linalg.inv(R21),R21),'Rinv,R':(np.linalg.inv(Rm),Rm),'R21,R21inv':(R21,np.linalg.inv(R21))}
# relation: y_kl x_ij = sum A[(i,k),(i',k')] x_{i'j'} y_{k'l'} A'[(j',l'),(j,l)]
def ok(A,Ap,badx,bady):
    # check: for bad x_ij, every term with nonzero coefficient has x bad; for bad y_kl every term has y bad
    for i,j,k,l in itertools.product(range(n),repeat=4):
        for i2,j2,k2,l2 in itertools.product(range(n),repeat=4):
            c=A[i*n+k,i2*n+k2]*Ap[j2*n+l2,j*n+l]
            if abs(c)>1e-12:
                if badx(i,j) and not badx(i2,j2): return False
                if bady(k,l) and not bady(k2,l2): return False
    return True
up=lambda a,b:a<b; lo=lambda a,b:a>b
for name,(A,Ap) in cands.items():
    print(name,'X lower(bad upper),Y upper:',ok(A,Ap,up,lo),' X upper,Y lower:',ok(A,Ap,lo,up))
EOF
python3 /tmp/r3/tri.py

